import{_ as a,o as s,c as e,a3 as n}from"./chunks/framework.B9qR_F1m.js";const m=JSON.parse('{"title":"借贷记账法与会计分录","description":"讲清\\"借\\"\\"贷\\"作为记账符号的含义、各类账户的增减方向、记账规则与试算平衡，并给出 8 类常见业务的标准分录。","frontmatter":{"title":"借贷记账法与会计分录","date":"2026-10-18T00:00:00.000Z","subject":"accounting","subjectLabel":"会计学","category":"基础会计","tags":["借贷记账法","会计分录","复式记账"],"description":"讲清\\"借\\"\\"贷\\"作为记账符号的含义、各类账户的增减方向、记账规则与试算平衡，并给出 8 类常见业务的标准分录。"},"headers":[],"relativePath":"subjects/accounting/fundamentals/journal-entries.md","filePath":"subjects/accounting/fundamentals/journal-entries.md","lastUpdated":null}'),r={name:"subjects/accounting/fundamentals/journal-entries.md"};function l(o,t,d,i,p,c){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="借贷记账法与会计分录" tabindex="-1">借贷记账法与会计分录 <a class="header-anchor" href="#借贷记账法与会计分录" aria-label="Permalink to &quot;借贷记账法与会计分录&quot;">​</a></h1><blockquote><p><strong>一句话概括</strong>：&quot;借&quot;&quot;贷&quot;只是左、右两个方向的代号，真正的规则只有一条——有借必有贷，借贷必相等。</p></blockquote><h2 id="一、-借-与-贷-的含义" tabindex="-1">一、&quot;借&quot;与&quot;贷&quot;的含义 <a class="header-anchor" href="#一、-借-与-贷-的含义" aria-label="Permalink to &quot;一、&quot;借&quot;与&quot;贷&quot;的含义&quot;">​</a></h2><p>&quot;借&quot;&quot;贷&quot;最初来源于借贷资本家的债权债务记录，如今已完全符号化： <strong>借方 = 账户的左方，贷方 = 账户的右方</strong>，不再具有字面意义。</p><h2 id="二、账户结构与增减方向" tabindex="-1">二、账户结构与增减方向 <a class="header-anchor" href="#二、账户结构与增减方向" aria-label="Permalink to &quot;二、账户结构与增减方向&quot;">​</a></h2><p>账户的哪一方记增加，取决于账户的<strong>性质</strong>：</p><table tabindex="0"><thead><tr><th>账户类别</th><th>借方</th><th>贷方</th><th>余额方向</th><th>期末余额公式</th></tr></thead><tbody><tr><td>资产</td><td>增加</td><td>减少</td><td>借方</td><td>期初借方 + 本期借方 − 本期贷方</td></tr><tr><td>费用（成本）</td><td>增加</td><td>减少</td><td>借方（一般无余额）</td><td>期末结转后无余额</td></tr><tr><td>负债</td><td>减少</td><td>增加</td><td>贷方</td><td>期初贷方 + 本期贷方 − 本期借方</td></tr><tr><td>所有者权益</td><td>减少</td><td>增加</td><td>贷方</td><td>期初贷方 + 本期贷方 − 本期借方</td></tr><tr><td>收入</td><td>减少</td><td>增加</td><td>贷方（一般无余额）</td><td>期末结转后无余额</td></tr></tbody></table><p>记忆口诀：<strong>资产费用借增贷减，负债权益收入贷增借减</strong>。 这与扩展会计等式 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>资产</mtext><mo>+</mo><mtext>费用</mtext><mo>=</mo><mtext>负债</mtext><mo>+</mo><mtext>所有者权益</mtext><mo>+</mo><mtext>收入</mtext></mrow><annotation encoding="application/x-tex">\\text{资产} + \\text{费用} = \\text{负债} + \\text{所有者权益} + \\text{收入}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">资产</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">费用</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">负债</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">所有者权益</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">收入</span></span></span></span></span> 的左右两边完全对应——等式左边的项目借方记增加，右边的项目贷方记增加。</p><h2 id="三、记账规则与分录格式" tabindex="-1">三、记账规则与分录格式 <a class="header-anchor" href="#三、记账规则与分录格式" aria-label="Permalink to &quot;三、记账规则与分录格式&quot;">​</a></h2><h3 id="记账规则" tabindex="-1">记账规则 <a class="header-anchor" href="#记账规则" aria-label="Permalink to &quot;记账规则&quot;">​</a></h3><p><strong>有借必有贷，借贷必相等</strong>。每一笔业务至少影响两个账户， 且借方金额合计必然等于贷方金额合计。</p><h3 id="分录书写格式" tabindex="-1">分录书写格式 <a class="header-anchor" href="#分录书写格式" aria-label="Permalink to &quot;分录书写格式&quot;">​</a></h3><p>先借后贷，借贷分行，贷方后退两格，金额各自对齐：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>借：原材料                      20 000</span></span>
<span class="line"><span>    贷：应付账款——甲公司                20 000</span></span></code></pre></div><p>复合分录允许&quot;一借多贷&quot;或&quot;一贷多借&quot;，但<strong>不允许&quot;多借多贷&quot;</strong>， 否则会掩盖账户之间的对应关系，不利于查账。</p><h2 id="四、编制分录的三步法" tabindex="-1">四、编制分录的三步法 <a class="header-anchor" href="#四、编制分录的三步法" aria-label="Permalink to &quot;四、编制分录的三步法&quot;">​</a></h2><ol><li><strong>判性质</strong>：判断业务涉及哪些科目，各属于哪一类；</li><li><strong>定方向</strong>：判断各科目的金额是增还是减，再换算成借或贷；</li><li><strong>平金额</strong>：检查借贷双方合计是否相等。</li></ol><h2 id="五、常见业务分录示例" tabindex="-1">五、常见业务分录示例 <a class="header-anchor" href="#五、常见业务分录示例" aria-label="Permalink to &quot;五、常见业务分录示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务</th><th>会计分录（单位：元）</th></tr></thead><tbody><tr><td>从银行提取现金 5 000</td><td>借：库存现金 5 000 / 贷：银行存款 5 000</td></tr><tr><td>赊销商品 30 000，成本 22 000</td><td>借：应收账款 30 000 / 贷：主营业务收入 30 000<br>借：主营业务成本 22 000 / 贷：库存商品 22 000</td></tr><tr><td>购入不需安装的设备 80 000，款项已付</td><td>借：固定资产 80 000 / 贷：银行存款 80 000</td></tr><tr><td>计提本月折旧 6 000（管理部门）</td><td>借：管理费用 6 000 / 贷：累计折旧 6 000</td></tr><tr><td>计提本月工资，其中生产工人 40 000、管理人员 15 000</td><td>借：生产成本 40 000 / 管理费用 15 000 / 贷：应付职工薪酬 55 000</td></tr><tr><td>预收客户货款 10 000</td><td>借：银行存款 10 000 / 贷：合同负债 10 000</td></tr><tr><td>月末结转收入类账户</td><td>借：主营业务收入 30 000 / 贷：本年利润 30 000</td></tr><tr><td>月末结转费用类账户</td><td>借：本年利润 28 000 / 贷：主营业务成本 22 000 / 管理费用 6 000</td></tr></tbody></table><blockquote><p><strong>注意</strong>：预收款项不是收入，收到时形成的是<strong>合同负债</strong>，只有在履行履约义务后才能确认收入。</p></blockquote><h2 id="六、试算平衡" tabindex="-1">六、试算平衡 <a class="header-anchor" href="#六、试算平衡" aria-label="Permalink to &quot;六、试算平衡&quot;">​</a></h2><p>期末将所有账户的本期发生额与余额汇总，编制试算平衡表，检查三条平衡关系：</p><ol><li>全部账户<strong>借方期初余额合计 = 贷方期初余额合计</strong>；</li><li>全部账户<strong>借方本期发生额合计 = 贷方本期发生额合计</strong>；</li><li>全部账户<strong>借方期末余额合计 = 贷方期末余额合计</strong>。</li></ol><h3 id="试算平衡的局限" tabindex="-1">试算平衡的局限 <a class="header-anchor" href="#试算平衡的局限" aria-label="Permalink to &quot;试算平衡的局限&quot;">​</a></h3><p>以下六种错误<strong>不会</strong>破坏试算平衡，无法通过试算表发现：</p><ol><li>漏记整笔业务；</li><li>重复记录整笔业务；</li><li>记错账户（科目用错，但借贷金额仍相等）；</li><li>借贷双方同时多记或少记相同金额；</li><li>一笔业务的借贷方向同时记反；</li><li>两个错误恰好相互抵消。</li></ol><p>因此试算平衡只是<strong>必要条件</strong>，不是记账无误的充分证明。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确做法</th></tr></thead><tbody><tr><td>&quot;借&quot;就是&quot;借钱进来&quot;</td><td>只是左方符号，与字面意思无关</td></tr><tr><td>把所有分录都写成&quot;一借一贷&quot;</td><td>复合业务应写复合分录，但要避免多借多贷</td></tr><tr><td>收到现金就确认收入</td><td>需判断是否已履行履约义务</td></tr></tbody></table><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>《企业会计准则——基本准则》</li><li>初级会计实务教材第二章</li></ul>`,31)])])}const u=a(r,[["render",l]]);export{m as __pageData,u as default};
